from __future__ import annotations

import os
from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final = Path("notes")


def read_note(name: str) -> str:
    """Return the text of `name` inside NOTES_DIR.

    Only regular files that resolve to a location inside NOTES_DIR are read.
    Absolute paths, `..` components, and symlinks that point outside
    NOTES_DIR are refused. A missing, unreadable, or refused file yields "".
    """
    try:
        base = NOTES_DIR.resolve()
        target = (base / name).resolve()
    except (OSError, ValueError):
        return ""
    if target == base or not target.is_relative_to(base):
        return ""
    try:
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return ""


@pytest.fixture
def notes_env(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    """Run each test from a temp cwd that contains an empty notes/ dir."""
    monkeypatch.chdir(tmp_path)
    notes = tmp_path / "notes"
    notes.mkdir()
    return notes


def test_reads_existing_note(notes_env: Path) -> None:
    (notes_env / "a.txt").write_text("hello", encoding="utf-8")
    assert read_note("a.txt") == "hello"


def test_reads_note_in_subdirectory(notes_env: Path) -> None:
    (notes_env / "sub").mkdir()
    (notes_env / "sub" / "b.txt").write_text("x", encoding="utf-8")
    assert read_note("sub/b.txt") == "x"


def test_missing_file_gives_empty(notes_env: Path) -> None:
    assert read_note("nope.txt") == ""


def test_directory_gives_empty(notes_env: Path) -> None:
    (notes_env / "d").mkdir()
    assert read_note("d") == ""


def test_parent_traversal_blocked(notes_env: Path, tmp_path: Path) -> None:
    (tmp_path / "secret.txt").write_text("top secret", encoding="utf-8")
    assert read_note("../secret.txt") == ""


def test_nested_traversal_blocked(notes_env: Path, tmp_path: Path) -> None:
    (tmp_path / "secret.txt").write_text("top secret", encoding="utf-8")
    assert read_note("sub/../../secret.txt") == ""


def test_absolute_path_blocked(notes_env: Path, tmp_path: Path) -> None:
    secret = tmp_path / "secret.txt"
    secret.write_text("top secret", encoding="utf-8")
    assert read_note(str(secret.resolve())) == ""


def test_symlink_escape_blocked(notes_env: Path, tmp_path: Path) -> None:
    secret = tmp_path / "secret.txt"
    secret.write_text("top secret", encoding="utf-8")
    os.symlink(secret, notes_env / "link.txt")
    assert read_note("link.txt") == ""
